mapper.select:
SELECT v.video_id AS videoId, v.thumbnail_url AS thumbnailUrl, v.view_count AS viewCount FROM video v LEFT JOIN category c ON v.category_id = c.category_id WHERE 1=1
AND c.category_name = #{categoryName}
ORDER BY
v.view_count DESC, v.created_at DESC
v.created_at DESC
LIMIT #{size} OFFSET #{offset}
